from fixtures import load_fixtures, ROWS
from running import running_goals, final_goals

VALUES = [v for _, v in ROWS]


def test_length():
    assert len(running_goals(list(load_fixtures()))) == len(ROWS)


def test_final():
    assert final_goals(list(load_fixtures())) == sum(VALUES)


def test_first_entry():
    assert running_goals(list(load_fixtures()))[0] == VALUES[0]


def test_single():
    assert running_goals(list(load_fixtures())[:1]) == [VALUES[0]]


def test_empty():
    assert running_goals([]) == [] and final_goals([]) == 0
